// Generated by split_s24_performance_examples.py.
//
// S24 generation and diagnostics live outside presentation so every focused
// screen can execute one public generator and display that exact function as
// `Dart usage code`.

import 'dart:typed_data';

import 'package:flutter/material.dart' show TextDirection;
import 'package:genius_link_pdf_generator/genius_link_pdf_generator.dart'
    hide EdgeInsets, Colors;

/// Small diagnostic document shared by the focused S24 scenarios.
final class S24PerformanceRegressionVerificationDocument
    extends GeniusPdfDocumentBuilder {
  S24PerformanceRegressionVerificationDocument(
    super.config, {
    required this.scenario,
    required this.diagnostic,
    required this.rows,
    required this.rtl,
  });

  final String scenario;
  final String diagnostic;
  final int rows;
  final bool rtl;

  @override
  void build() {
    newPage();
    addLine(
      'S24 — $scenario',
      font: config.headerFont,
      topMargin: 4,
    );
    addLine(diagnostic);
    addLine(rtl ? 'الاتجاه: RTL' : 'Direction: LTR');
    addSpace(8);
    for (var index = 0; index < rows; index++) {
      addLine(
        rtl
            ? 'سطر تحقق ${index + 1} — INV-${index + 1} — 1150.00 SAR'
            : 'Verification row ${index + 1} — INV-${index + 1} — 1150.00 SAR',
        font: config.smallFont,
      );
    }
  }
}

Future<Uint8List> buildS24FamilyBenchmarkVerificationPdf(
  GeniusPdfConfig config, {
  int rows = 50,
}) async {
  const runner = GeniusPdfPerformanceBenchmarkRunner();
  final result = await runner.run(
    GeniusPdfBenchmarkCase(
      id: 'manual-family-benchmark',
      family: GeniusPdfBenchmarkFamily.transaction,
      iterations: 3,
      generate: () => List<int>.filled(rows * 10, 1),
    ),
  );

  final diagnostic = 'iterations=${result.iterations}; '
      'avgMs=${result.averageMilliseconds.toStringAsFixed(3)}; '
      'bytes=${result.totalOutputBytes}';
  final rtl = config.textDirection == TextDirection.rtl;
  final document = S24PerformanceRegressionVerificationDocument(
    config,
    scenario: 'Family Benchmark',
    diagnostic: diagnostic,
    rows: rows,
    rtl: rtl,
  );

  try {
    return Uint8List.fromList(document.generate());
  } finally {
    document.dispose();
  }
}

Future<Uint8List> buildS24MeasurementCacheVerificationPdf(
  GeniusPdfConfig config, {
  int rows = 50,
}) async {
  final cache = GeniusPdfMeasurementCache();
  var calls = 0;
  const key = GeniusPdfMeasurementKey(
    contentHash: 101,
    widthMicros: 300000,
    styleHash: 202,
    direction: 'auto',
  );

  for (var index = 0; index < rows; index++) {
    cache.measure(key, () {
      calls++;
      return 40;
    });
  }

  final diagnostic = 'measurementCalls=$calls; '
      'cacheEntries=${cache.length}; requested=$rows';
  final rtl = config.textDirection == TextDirection.rtl;
  final document = S24PerformanceRegressionVerificationDocument(
    config,
    scenario: 'Resource / Measurement Cache',
    diagnostic: diagnostic,
    rows: rows,
    rtl: rtl,
  );

  try {
    return Uint8List.fromList(document.generate());
  } finally {
    document.dispose();
  }
}

Future<Uint8List> buildS24SemanticRegressionVerificationPdf(
  GeniusPdfConfig config, {
  int rows = 50,
}) async {
  final rtl = config.textDirection == TextDirection.rtl;
  const checker = GeniusPdfSemanticRegression();
  final expectation = GeniusPdfSemanticRegression.erpDocument(
    documentNumber: 'INV-LATIN-001',
    party: rtl ? 'عميل تجريبي' : 'Demo Customer',
    total: '1150.00',
    tax: '150.00',
    currency: 'SAR',
    pageNumber: '1/1',
    complianceMetadata: const <String>['UUID-DEMO-001'],
  );
  final source = <String>[
    'INV-LATIN-001',
    rtl ? 'عميل تجريبي' : 'Demo Customer',
    '1000.00',
    '150.00',
    '1150.00',
    'SAR',
    '1/1',
    'UUID-DEMO-001',
  ].join(' ');
  final result = checker.checkExtractedText(source, expectation);
  final diagnostic = 'semanticPass=${result.passed}; '
      'missing=${result.missing}; forbidden=${result.forbiddenFound}';

  final document = S24PerformanceRegressionVerificationDocument(
    config,
    scenario: 'Semantic Regression',
    diagnostic: diagnostic,
    rows: rows,
    rtl: rtl,
  );

  try {
    return Uint8List.fromList(document.generate());
  } finally {
    document.dispose();
  }
}

